import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第三十八卦 睽 火澤睽 離上兌下","description":"周易 - 第三十八卦 睽 火澤睽 離上兌下","frontmatter":{"title":"第三十八卦 睽 火澤睽 離上兌下","description":"周易 - 第三十八卦 睽 火澤睽 離上兌下"},"headers":[],"relativePath":"classics/zhouyi/039.md","filePath":"classics/zhouyi/039.md"}'),l={name:"classics/zhouyi/039.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="睽" tabindex="-1">睽 <a class="header-anchor" href="#睽" aria-label="Permalink to “睽”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>小事吉。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>睽，火動而上，澤動而下；二女同居，其志不同行；說而麗乎明，柔進而上行，得中而應乎剛；是以小事吉。天地睽，而其事同也；男女睽，而其志通也；萬物睽，而其事 類也；睽之時用大矣哉！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>上火下澤，睽；君子以同而異。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>悔亡，喪馬勿逐，自復；見惡人無咎。象 曰：見惡人，以闢咎也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>遇主於巷，無咎。象曰：遇主於巷，未失道也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>見輿曳，其牛掣，其人天且劓，無初有終。象曰：見輿曳，位不當也。無初有終，遇剛也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>睽孤，遇元夫，交孚，厲無咎。象曰：交孚無咎，志行也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>悔亡，厥宗噬膚，往何咎。象曰：厥宗噬膚，往有慶也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧，匪寇婚媾，往遇雨則吉。象曰：遇雨之吉，群疑亡也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
